//! Bake data into the binary at build time: the contributor credits as static Rust tables
//! (craftrules standards/contributors.md) and the UI translation catalogs as deflated blobs.
//!
//! Nothing is read at run time.
//!
//! - contributors/contributors.json: commit stats per GitHub username, generated by craftrules
//!   scripts/contributors.py, which also marks whose people.toml entry it verified.
//! - contributors/people.toml: the names people chose for themselves. A name is used only when the
//!   JSON says the entry was verified (`people_entry`).
//! - src/i18n/*.tsv: one UTF-8 catalog per language, `context<TAB>source<TAB>translation`, English
//!   source strings as the keys. They are packed into `OUT_DIR/i18n/`: one keys table shared by
//!   every language plus one file per language that stores translations with short relative key
//!   references. Both are deflated; the UI inflates them on the first use. This is what keeps the
//!   web build small enough (see docs/localization.md).
//!
//! A missing or malformed contributors file gives empty tables (or no names) and a warning. A
//! malformed catalog line is kept verbatim with a warning, so the runtime parser reports it and
//! the catalog tests fail instead of silently dropping a translation.

use std::collections::HashMap;
use std::fmt::Write as _;
use std::io::Write as _;
use std::path::{Path, PathBuf};

use serde_json::Value;

fn main() {
    credits();
    pack_catalogs();
}

fn manifest_dir() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).to_path_buf()
}

fn out_dir() -> PathBuf {
    PathBuf::from(std::env::var_os("OUT_DIR").unwrap_or_default())
}

// ---------------------------------------------------------------------------------------------
// Contributor credits (craftrules standards/contributors.md)
// ---------------------------------------------------------------------------------------------

fn credits() {
    let dir = manifest_dir().join("../../contributors");
    let json = read(&dir.join("contributors.json"), "the About window shows no contributors", |t| {
        serde_json::from_str::<Value>(t).map_err(|e| e.to_string())
    })
    .unwrap_or(Value::Null);
    let people = read(&dir.join("people.toml"), "contributors are shown by username only", |t| t.parse::<toml::Table>().map_err(|e| e.to_string()))
        .unwrap_or_default();
    let out = out_dir().join("credits.rs");
    if let Err(e) = std::fs::write(&out, generate(&json, &people)) {
        println!("cargo::warning=writing {}: {e}", out.display());
    }
}

fn read<T>(path: &std::path::Path, fallback: &str, parse: impl Fn(&str) -> Result<T, String>) -> Option<T> {
    println!("cargo::rerun-if-changed={}", path.display());
    let r = std::fs::read_to_string(path).map_err(|e| e.to_string()).and_then(|t| parse(&t));
    if let Err(e) = &r {
        println!("cargo::warning={}: {e}; {fallback}", path.display());
    }
    r.ok()
}

/// A non-empty string field of someone's people.toml entry, as a Rust `Option<&str>` literal.
fn name(v: Option<&str>) -> String {
    match v.map(str::trim).filter(|s| !s.is_empty()) {
        Some(x) => format!("Some({x:?})"),
        None => "None".into(),
    }
}

fn s(v: &Value, k: &str) -> String {
    format!("{:?}", v.get(k).and_then(Value::as_str).unwrap_or(""))
}

fn n(v: &Value, k: &str) -> u64 {
    v.get(k).and_then(Value::as_u64).unwrap_or(0)
}

fn rows(json: &Value, k: &str) -> Vec<Value> {
    json.get(k).and_then(Value::as_array).cloned().unwrap_or_default()
}

fn generate(json: &Value, people: &toml::Table) -> String {
    let mut o = String::new();
    let _ = writeln!(o, "pub static TOTAL_COMMITS: u64 = {};", n(json, "commits"));
    let _ = writeln!(o, "pub static CONTRIBUTORS: &[Contributor] = &[");
    for c in rows(json, "contributors") {
        let login = c.get("login").and_then(Value::as_str).unwrap_or("");
        if login.is_empty() {
            continue;
        }
        // Names only from a verified, self-chosen people.toml entry.
        let entry = people.get("people").and_then(|p| p.get(login)).filter(|_| c.get("people_entry").and_then(Value::as_bool) == Some(true));
        let field = |k: &str| entry.and_then(|e| e.get(k)).and_then(toml::Value::as_str);
        let synced = entry.and_then(|e| e.get("sync_github_name")).and_then(toml::Value::as_bool) == Some(true);
        let display = field("display_name")
            .filter(|s| !s.trim().is_empty())
            .or_else(|| if synced { c.get("github_name").and_then(Value::as_str) } else { None });
        let _ = writeln!(
            o,
            "    Contributor {{ login: {login:?}, display_name: {}, real_name: {}, prs: {}, commits: {}, lines_added: {}, lines_deleted: {}, binary_added: {}, binary_deleted: {}, first_commit: {}, last_commit: {} }},",
            name(display),
            name(field("real_name")),
            n(&c, "prs"),
            n(&c, "commits"),
            n(&c, "lines_added"),
            n(&c, "lines_deleted"),
            n(&c, "binary_added"),
            n(&c, "binary_deleted"),
            s(&c, "first_commit"),
            s(&c, "last_commit"),
        );
    }
    let _ = writeln!(o, "];");
    let _ = writeln!(o, "pub static MODELS: &[Model] = &[");
    for m in rows(json, "models") {
        let _ = writeln!(
            o,
            "    Model {{ company: {}, model: {}, version: {}, commits: {}, lines_added: {}, lines_deleted: {} }},",
            s(&m, "company"),
            s(&m, "model"),
            s(&m, "version"),
            n(&m, "commits"),
            n(&m, "lines_added"),
            n(&m, "lines_deleted"),
        );
    }
    let _ = writeln!(o, "];");
    o
}

// ---------------------------------------------------------------------------------------------
// Translation catalogs
// ---------------------------------------------------------------------------------------------

/// One line of a source catalog, before packing.
enum Line {
    /// `context<TAB>source<TAB>translation`: its key and translation are stored in the packed file.
    Entry { key: String, translation: String },
    /// A comment, a blank line, or a malformed line that is passed through verbatim.
    Raw(String),
}

/// Read one catalog, warning about every line that is not a valid entry.
fn read_catalog(text: &str) -> Vec<Line> {
    text.lines()
        .map(|line| {
            if line.trim().is_empty() || line.starts_with('#') {
                return Line::Raw(line.to_owned());
            }
            // `context<TAB>source<TAB>translation`, with no fourth column and no empty text.
            let mut cols = line.splitn(3, '\t');
            match (cols.next(), cols.next(), cols.next()) {
                (Some(ctx), Some(src), Some(tr)) if !src.is_empty() && !tr.is_empty() && !tr.contains('\t') => {
                    Line::Entry { key: format!("{ctx}\t{src}"), translation: tr.to_owned() }
                }
                _ => {
                    println!("cargo::warning=malformed catalog line: {line:?}");
                    Line::Raw(line.to_owned())
                }
            }
        })
        .collect()
}

/// Pack every catalog: one keys table shared by all languages, then one file per language in which
/// repeated keys are written as a one-byte marker (`\u{1}` = the next expected key) or as a short
/// signed offset from the next expected key (`\u{2}<offset><TAB>translation`). Comment lines stay
/// as they are; a raw line that happens to start with one of the markers is escaped with `\u{3}`.
fn pack_catalogs() {
    let dir = manifest_dir().join("src/i18n");
    println!("cargo::rerun-if-changed={}", dir.display());
    let mut catalogs: Vec<(String, Vec<Line>)> = Vec::new();
    match std::fs::read_dir(&dir) {
        Ok(entries) => {
            for entry in entries.flatten() {
                let path = entry.path();
                let (Some(extension), Some(stem)) = (path.extension().and_then(|e| e.to_str()), path.file_stem().and_then(|s| s.to_str())) else {
                    continue;
                };
                if extension != "tsv" {
                    continue;
                }
                println!("cargo::rerun-if-changed={}", path.display());
                match std::fs::read_to_string(&path) {
                    Ok(text) => catalogs.push((stem.to_owned(), read_catalog(&text))),
                    Err(e) => println!("cargo::warning=reading {}: {e}", path.display()),
                }
            }
        }
        Err(e) => println!("cargo::warning=reading {}: {e}", dir.display()),
    }
    // Largest catalog first: it defines the key order, so smaller catalogs mostly reference
    // neighbouring keys and need few offsets.
    catalogs.sort_by(|a, b| b.1.len().cmp(&a.1.len()).then_with(|| a.0.cmp(&b.0)));

    // Keys are numbered once, in first-appearance order across all catalogs.
    let mut keys: Vec<String> = Vec::new();
    let mut key_index: HashMap<&str, usize> = HashMap::new();
    for (_, lines) in &catalogs {
        for line in lines {
            if let Line::Entry { key, .. } = line
                && !key_index.contains_key(key.as_str())
            {
                key_index.insert(key, keys.len());
                keys.push(key.clone());
            }
        }
    }

    let out = out_dir().join("i18n");
    if let Err(e) = std::fs::create_dir_all(&out) {
        println!("cargo::warning=creating {}: {e}", out.display());
        return;
    }
    if let Err(e) = std::fs::write(out.join("keys.deflate"), deflate(keys.join("\n").as_bytes())) {
        println!("cargo::warning=writing the keys table: {e}");
    }
    for (code, lines) in &catalogs {
        let packed = pack_catalog(lines, &key_index);
        let path = out.join(format!("{code}.tsv.deflate"));
        if let Err(e) = std::fs::write(&path, deflate(packed.as_bytes())) {
            println!("cargo::warning=writing {}: {e}", path.display());
        }
    }
}

fn pack_catalog(lines: &[Line], key_index: &HashMap<&str, usize>) -> String {
    let mut out = String::new();
    // Index of the key the next entry is expected to have, so it can be encoded as `\u{1}`.
    let mut next = 0usize;
    for (n, line) in lines.iter().enumerate() {
        if n > 0 {
            out.push('\n');
        }
        match line {
            Line::Entry { key, translation } => {
                let index = key_index.get(key.as_str()).copied().unwrap_or(next);
                if index == next {
                    out.push('\u{1}');
                } else {
                    out.push('\u{2}');
                    out.push_str(&(index as i64 - next as i64).to_string());
                    out.push('\t');
                }
                out.push_str(translation);
                next = index.saturating_add(1);
            }
            Line::Raw(raw) => {
                // A raw line starting with a marker byte must not be read as an entry.
                if raw.starts_with(['\u{1}', '\u{2}', '\u{3}']) {
                    out.push('\u{3}');
                }
                out.push_str(raw);
            }
        }
    }
    out
}

fn deflate(bytes: &[u8]) -> Vec<u8> {
    let mut encoder = flate2::write::DeflateEncoder::new(Vec::new(), flate2::Compression::best());
    if let Err(e) = encoder.write_all(bytes) {
        println!("cargo::warning=deflating a catalog: {e}");
        return Vec::new();
    }
    match encoder.finish() {
        Ok(done) => done,
        // An empty blob would unpack to an empty catalog at run time — warn loudly instead of
        // shipping it silently (the catalog tests also fail on it).
        Err(e) => {
            println!("cargo::warning=finishing a deflated catalog: {e}");
            Vec::new()
        }
    }
}
